// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNum, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        blockNum = bound(blockNum, block.number, block.number + 100000);
        vm.assume(blockNum % 15 != 0);
        vm.roll(blockNum);
        vm.deal(actor, 10 ether);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok && address(c).balance == balBefore + 10 ether);
    }
}
